CREATE VIEW "Z_TEST_PRODUCTION_20250925"."ixvITL_LastWhs" ( "ItemCode", "SysNumber", "WhsCode" ) AS SELECT		T0."ItemCode", lastLogEntry."SysNumber", T0."LocCode" AS "WhsCode" FROM		"Z_TEST_PRODUCTION_20250925".OITL  T0 INNER JOIN	(SELECT	MAX("LogEntry") AS "LogEntry", "ItemCode", "SysNumber" FROM "Z_TEST_PRODUCTION_20250925".ITL1 GROUP BY "ItemCode", "SysNumber") AS lastLogEntry ON lastLogEntry."LogEntry" = T0."LogEntry" AND T0."ItemCode" = lastLogEntry."ItemCode" WITH READ ONLY